const rows = $input.all().map(i => i.json);

// Restyle rules applied to memo_html only:
//  headings colour -> black; all body font sizes -> 14px (uniform)
function restyle(html) {
  let out = String(html == null ? '' : html);
  out = out.split('color:#0b2e59').join('color:#000000');   // navy headings + inline labels
  out = out.split('color:#5a6472').join('color:#000000');   // grey subtitle
  out = out.split('font-size:20px').join('font-size:14px');  // company name
  out = out.split('font-size:15px').join('font-size:14px');  // section headings
  out = out.split('font-size:13px').join('font-size:14px');  // subtitle
  return out;
}

let changed = 0, unchanged = 0;
const colorLeft = [];   // any memo still carrying a non-black heading colour
const sizeLeft = [];    // any memo still carrying a non-14px size
for (const r of rows) {
  const name = String(r.startup || r.startup_name || '(unknown)');
  const before = String(r.memo_html || '');
  if (!before) { unchanged++; continue; }
  const after = restyle(before);
  if (after !== before) changed++; else unchanged++;
  if (/color:#0b2e59|color:#5a6472/.test(after)) colorLeft.push(name);
  if (/font-size:(20|15|13)px/.test(after)) sizeLeft.push(name);
}

// Sample the first changed memo for eyeballing
let sample = null;
for (const r of rows) {
  const before = String(r.memo_html || '');
  if (!before) continue;
  const after = restyle(before);
  if (after !== before) { sample = { startup: r.startup || r.startup_name, before_head: before.slice(0, 700), after_head: after.slice(0, 700) }; break; }
}

return [{ json: {
  total: rows.length,
  will_change: changed,
  unchanged_or_empty: unchanged,
  color_residue_after: colorLeft,   // should be []
  size_residue_after: sizeLeft,     // should be []
  sample,
} }];
